style.css:
/* Adds a pink ribbon-style border around the entire Discord app */
body {
    border: 10px solid #ffb6c1 !important; /* Soft pink color */
    box-sizing: border-box !important;
    height: 100vh !important;
}

/* Optional: Adds a glow effect to make it feel more "kawaii" */
body {
    box-shadow: inset 0 0 15px rgba(255, 182, 193, 0.8) !important;
}
